    "a uses only the\n    buckets a request can actually write.\n    \"\"\"\n    out = {}\n    for su"
    "b in BUCKETS:\n        raw = sh([\"bash\", \"-c\", \"ls -1R %s/%s 2>/dev/null | grep -c . || tru"
    "e\" % (MINIO_DATA, sub)])\n        try:\n            out[sub] = int(raw or \"0\")\n        excep"
    "t Exception:\n            out[sub] = 0\n    return out\n\n\ndef minio_objects():\n    return sum"
    "(v for k, v in minio_bucket_counts().items() if \"raw\" not in k)\n\n\ndef minio_names():\n    "
    "\"\"\"Object NAMES, not only counts, for the buckets a request can write.\"\"\"\n    names = []"
    "\n    for sub in BUCKETS:\n        if \"raw\" in sub:\n            continue\n        out = sh(["
